const JS_MARKERS = [
	"package.json",
	"bun.lock",
	"bun.lockb",
	"pnpm-lock.yaml",
	"yarn.lock",
	"deno.json",
	"deno.jsonc",
	"tsconfig.json",
	"jsconfig.json",
];
const IGNORED_DIR = new Set([
	"node_modules",
	"target",
	"dist",
	".git",
	"vendor",
	".svelte-kit",
	"build",
	".output",
	".wxt",
]);

export type LintJob = {
	name: "dlint" | "clippy";
	command: string;
	args: string[];
	cwd: string;
	timeout: number;
};

export type LintPlan = { jobs: LintJob[]; notes: string[] };

/** One finished job; `output` is stdout and stderr joined and trimmed. */
