+	let scanProject = false;
+	let json = false;
+	const paths: string[] = [];
+	for (let i = 0; i < args.length; i++) {
+		const arg = args[i];
+		if (arg === "--scan") scanProject = true;
+		else if (arg === "--json") json = true;
+		else if (arg === "--cwd" && args[i + 1] !== undefined) cwd = resolve(args[++i]);
